import React, { useState, useEffect } from 'react';
import { useOLAPStore } from '../store/olap-store';
import { olap } from '../api/olap-client';

export const FilterPanel = ({ onApply }) => {
  const [customerTypes, setCustomerTypes] = useState([]);
  const [products, setProducts] = useState([]);
  const [stores, setStores] = useState([]);
  const [cities, setCities] = useState([]);
  const [loading, setLoading] = useState(false);

  const filters = useOLAPStore((state) => state.filters);
  const setFilters = useOLAPStore((state) => state.setFilters);
  const clearFilters = useOLAPStore((state) => state.clearFilters);

  useEffect(() => {
    loadMetadata();
  }, []);

  const loadMetadata = async () => {
    try {
      setLoading(true);
      const [ctypes, prods, strs, cts] = await Promise.all([
        olap.getCustomerTypes(),
        olap.getProducts(100),
        olap.getStores(),
        olap.getCities(),
      ]);

      // Log raw API responses
      console.log('🔍 Customer Types API:', ctypes.data);
      console.log('🔍 Products API:', prods.data);
      console.log('🔍 Stores API:', strs.data);

      // Transform data if needed
      const transformList = (items) => {
        if (!items) return [];
        // If already has value/label, return as-is
        if (items[0]?.value !== undefined) return items;
        // Otherwise, transform based on structure
        return items.map((item) => {
          if (typeof item === 'string') {
            return { value: item, label: item };
          }
          // If it's an object with different key names, map them
          return {
            value: item.customer_type || item.product_key || item.store_key || item.city || item.id || Object.values(item)[0],
            label: item.customer_type || item.product_key || item.store_key || item.city || item.name || Object.values(item)[0],
          };
        });
      };

      setCustomerTypes(transformList(ctypes.data));
      setProducts(transformList(prods.data));
      setStores(transformList(strs.data));
      setCities(transformList(cts.data));
    } catch (error) {
      console.error('❌ Error loading metadata:', error);
      alert('Lỗi tải metadata: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (field, value) => {
    setFilters({ ...filters, [field]: value || null });
  };

  const handleApply = () => {
    if (onApply) onApply();
  };

  return (
    <div className="filter-panel" style={{ padding: '15px', backgroundColor: '#f9f9f9', borderRadius: '6px', marginBottom: '15px' }}>
      <h3 style={{ marginBottom: '15px', color: '#333' }}>🔎 Slice & Dice (Filter)</h3>

      {loading && <p style={{ color: '#999' }}>Đang tải metadata...</p>}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '15px' }}>
        <div>
          <label style={{ fontWeight: '600', color: '#667eea', display: 'block', marginBottom: '5px' }}>
            Loại Khách Hàng
          </label>
          <select
            value={filters.customerType || ''}
            onChange={(e) => handleFilterChange('customerType', e.target.value)}
            style={{ width: '100%', padding: '8px', border: '2px solid #ddd', borderRadius: '4px' }}
          >
            <option value="">-- Tất cả --</option>
            {customerTypes.map((ct) => (
              <option key={ct.value} value={ct.value}>
                {ct.label}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label style={{ fontWeight: '600', color: '#667eea', display: 'block', marginBottom: '5px' }}>
            Sản Phẩm
          </label>
          <select
            value={filters.productKey || ''}
            onChange={(e) => handleFilterChange('productKey', e.target.value)}
            style={{ width: '100%', padding: '8px', border: '2px solid #ddd', borderRadius: '4px' }}
          >
            <option value="">-- Tất cả --</option>
            {products.map((p) => (
              <option key={p.value} value={p.value}>
                {p.label}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label style={{ fontWeight: '600', color: '#667eea', display: 'block', marginBottom: '5px' }}>
            Cửa Hàng
          </label>
          <select
            value={filters.storeKey || ''}
            onChange={(e) => handleFilterChange('storeKey', e.target.value)}
            style={{ width: '100%', padding: '8px', border: '2px solid #ddd', borderRadius: '4px' }}
          >
            <option value="">-- Tất cả --</option>
            {stores.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>

        <div style={{ display: 'flex', gap: '10px', alignItems: 'flex-end' }}>
          <button
            onClick={handleApply}
            style={{
              flex: 1,
              padding: '8px',
              backgroundColor: '#667eea',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              fontWeight: '600',
              cursor: 'pointer',
            }}
          >
            Áp Dụng
          </button>
          <button
            onClick={clearFilters}
            style={{
              flex: 1,
              padding: '8px',
              backgroundColor: '#ccc',
              color: '#333',
              border: 'none',
              borderRadius: '4px',
              fontWeight: '600',
              cursor: 'pointer',
            }}
          >
            Xóa Bộ Lọc
          </button>
        </div>
      </div>
    </div>
  );
};

export default FilterPanel;
